    "AAHI.L",
    "..HCCL",
    "GDDJ..",
    "GEEJFF"
]

def solve():
    # Identify cars and their positions
    cars = {}
    for r in range(6):
        for c in range(6):
            char = board[r][c]
            if char not in ('.', 'x'):
                if char not in cars:
                    cars[char] = []
                cars[char].append((r, c))

    # Determine orientation and length
    car_data = {}
    for name, coords in cars.items():
        coords.sort()
        r1, c1 = coords[0]
        r2, c2 = coords[1]
        orientation = 'H' if r1 == r2 else 'V'
        car_data[name] = {'coords': coords, 'orient': orientation, 'len': len(coords)}

    # Walls
    walls = set()
    for r in range(6):
        for c in range(6):
            if board[r][c] == 'x':
                walls.add((r, c))

    def get_state(current_cars):
        return tuple(sorted((name, tuple(coords)) for name, coords in current_cars.items()))

    start_state = {name: tuple(data['coords']) for name, data in car_data.items()}
    queue = deque([(start_state, "")])
    visited = {get_state(start_state)}

    while queue:
        curr_cars, path = queue.popleft()

        # Check if AA reached exit (r=2, c=4,5)
        if curr_cars['AA'][1] == (2, 5):
            return path.strip()

