        for name, coords in curr_cars.items():
            orient = car_data[name]['orient']
            length = car_data[name]['len']

            if orient == 'H':
                r, c_start = coords[0]
                _, c_end = coords[-1]
                # Move Right
                if c_end + 1 < 6 and (r, c_end + 1) not in occupied:
                    new_coords = tuple((r, c + 1) for c in range(c_start, c_end + 1))
                    new_cars = dict(curr_cars)
                    new_cars[name] = new_coords
                    st = get_state(new_cars)
                    if st not in visited:
                        visited.add(st)
                        queue.append((new_cars, path + f"{name}+1 "))
                # Move Left
                if c_start - 1 >= 0 and (r, c_start - 1) not in occupied:
                    new_coords = tuple((r, c - 1) for c in range(c_start, c_end + 1))
                    new_cars = dict(curr_cars)
                    new_cars[name] = new_coords
                    st = get_state(new_cars)
                    if st not in visited:
                        visited.add(st)
                        queue.append((new_cars, path + f"{name}-1 "))
            else: # Vertical
                r_start, c = coords[0]
                r_end, _ = coords[-1]
                # Move Down
                if r_end + 1 < 6 and (r_end + 1, c) not in occupied:
                    new_coords = tuple((r + 1, c) for r in range(r_start, r_end + 1))
                    new_cars = dict(curr_cars)
                    new_cars[name] = new_coords
                    st = get_state(new_cars)
                    if st not in visited:
                        visited.add(st)
                        queue.append((new_cars, path + f"{name}+1 "))
                # Move Up
                if r_start - 1 >= 0 and (r_start - 1, c) not in occupied:
                    new_coords = tuple((r - 1, c) for r in range(r_start, r_end + 1))
                    new_cars = dict(curr_cars)
                    new_cars[name] = new_coords
                    st = get_state(new_cars)
                    if st not in visited:
                        visited.add(st)
                        queue.append((new_cars, path + f"{name}-1 "))
    return "No solution"

print(solve())"}

